#!/usr/bin/env bash
# Push the dynamic GATE 7R badge to the `badges` branch (orphan commit, force push).
# Requires: gate-report/gate7r.svg generated by scripts/gate_report.py,
#           GITHUB_TOKEN in env, run from repository root.
set -euo pipefail

STATUS="${1:-FAIL}"
SHA="${GITHUB_SHA:-unknown}"
SRC="gate-report/gate7r.svg"
[ -f "$SRC" ] || { echo "missing $SRC" >&2; exit 1; }

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
cd "$TMP"
git init -q -b badges
git config user.name "gate-bot"
git config user.email "actions@users.noreply.github.com"
mkdir -p badges
cp "$OLDPWD/$SRC" badges/gate7r.svg
git add -A
git commit -q -m "badge: GATE 7R ${STATUS} @ ${SHA}"
git remote add origin "https://x-access-token:${GITHUB_TOKEN}@github.com/${GITHUB_REPOSITORY}.git"
git push -q -f origin badges
echo "badge pushed: ${GITHUB_REPOSITORY} (badges branch), status=${STATUS}"
